// IMPOSTAZIONI · modifica solo questi valori
return [{
  json: {
    // URL del progetto Supabase (Project Settings → API), senza / finale
    supabase_url: 'https://IL-TUO-PROGETTO.supabase.co',
    // Modello Claude che interpreta i comandi vocali
    modello: 'claude-opus-5-5',
    // Livello di ragionamento: 'low' risponde in pochi secondi
    effort: 'low',
    // Modello OpenAI che trascrive i messaggi vocali di Telegram
    modello_trascrizione: 'whisper-1',
  },
}];

// Capisce cosa è arrivato da Telegram: vocale, testo o pulsante premuto.
const u = $('Telegram').first().json;
if (u.callback_query) {
  const q = u.callback_query;
  const [scelta, id] = String(q.data || '').split(':');
  return [{ json: { _dest: 'pulsante', chat_id: String(q.message.chat.id), query_id: q.id, comando_id: id, conferma: scelta === 'ok' } }];
}
const m = u.message;
if (!m) return [];
const chat_id = String(m.chat.id);
const vocale = m.voice || m.audio;
if (vocale) return [{ json: { _dest: 'vocale', chat_id, file_id: vocale.file_id } }];
if (m.text) {
  const collega = m.text.trim().match(/^\/collega(?:@\w+)?\s+(\S+@\S+)\s+(-?\d+)\s*$/i);
  if (collega) return [{ json: { _dest: 'collega', chat_id, email: collega[1].toLowerCase(), codice: collega[2] } }];
  if (/^\/collega\b/i.test(m.text.trim())) {
    return [{ json: { _dest: 'collega', chat_id, errore: 'Scrivi così: /collega email codice\nEsempio: /collega enrico.berte@gmail.com 123456789' } }];
  }
  if (m.text.startsWith('/start')) {
    return [{ json: { _dest: 'testo', chat_id, testo_utente: '', saluto: true } }];
  }
  return [{ json: { _dest: 'testo', chat_id, testo_utente: m.text.trim() } }];
}
return [];

// Testo del messaggio: trascritto dal vocale oppure scritto.
const t = $('Tipo di messaggio').first().json;
const testo = t._dest === 'vocale' ? String($json.text || '').trim() : t.testo_utente;
return [{ json: { chat_id: t.chat_id, testo_utente: testo, saluto: !!t.saluto } }];

// Prepara la richiesta a Claude con i soli dati che l'utente può vedere.
const CFG = $('IMPOSTAZIONI').first().json;
const ingresso = $('Unisci testo').first().json;
const ctx = $json;
const chat_id = ingresso.chat_id;

if (!ctx.collegato) {
  return [{ json: { _dest: 'rispondi', chat_id, testo:
    `Questo account Telegram non è ancora collegato al CRM.\nIl tuo codice è: ${chat_id}\nMandalo all'amministratore, che lo collega alla tua email.` } }];
}
if (ingresso.saluto || !ingresso.testo_utente) {
  return [{ json: { _dest: 'rispondi', chat_id, testo:
    `Ciao ${ctx.nome}. Mandami un vocale o un messaggio, per esempio:\n` +
    '• «Ho chiamato Marco Rossi, richiamalo tra 15 giorni»\n' +
    '• «Collega Anna Verdi con Lucia Bianchi, sono amiche»\n' +
    '• «Chi non sento da tre mesi?»\n' +
    'Prima di salvare ti chiedo sempre conferma.' +
    (ctx.ruolo === 'admin' ? '\n\nPer collegare un\'altra persona: chiedile di scrivermi /start e poi scrivi /collega email codice' : '') } }];
}

const dati = {
  oggi: ctx.oggi,
  utente: { nome: ctx.nome, ruolo: ctx.ruolo, puo_scrivere: ctx.puo_scrivere },
  settori: ctx.settori,
  persone: ctx.persone,
  relazioni: ctx.relazioni,
  trattative: ctx.trattative,
  attivita: ctx.attivita,
};

const istruzioni = `Sei l'assistente di un CRM italiano basato sulle relazioni tra persone. L'utente ha dettato un messaggio: può contenere errori di trascrizione nei nomi. Trasformalo in azioni sul CRM oppure rispondi alle domande usando SOLO i dati forniti.

DATI (JSON): ${JSON.stringify(dati)}

MESSAGGIO DELL'UTENTE: """${ingresso.testo_utente}"""

Rispondi SOLO con un oggetto JSON, senza testo prima o dopo, con questa forma:
{"azioni":[...], "risposta":"testo per l'utente, vuoto se ci sono solo azioni"}
Azioni ammesse (per "persona", "da", "a" usa l'id esistente; per una persona nuova creata nello stesso messaggio usa il suo nome esatto):
{"tipo":"crea_persona","nome":"","tipoScheda":"persona|azienda","ruolo":"","azienda":"","settori":["id settore"],"telefono":"","email":"","citta":""}
{"tipo":"aggiorna_persona","persona":"id","campi":{"telefono|email|citta|ruolo|azienda":"valore"}}
{"tipo":"crea_relazione","da":"id o nome","a":"id o nome","relazione":"conoscenza|amicizia|parentela|collaborazione|presentazione|socio|cliente|fornitore","nota":""}  (per "presentazione": "da" è chi ha presentato)
{"tipo":"registra_contatto","persona":"id","canale":"chiamata|appuntamento|messaggio","testo":"riassunto di cosa ci si è detti"}
{"tipo":"crea_attivita","persona":"id o null","attivita":"chiamata|appuntamento|promemoria","data":"AAAA-MM-GG","ora":"HH:MM o vuoto","testo":"cosa fare, breve"}
{"tipo":"aggiungi_nota","persona":"id","testo":""}
{"tipo":"crea_trattativa","titolo":"","persona":"id o null","settore":"id","importo":0,"fase":"Contatto|Proposta|Trattativa|Vinta|Persa","scadenza":"AAAA-MM-GG o null"}
{"tipo":"aggiorna_trattativa","trattativa":"id","fase":"Contatto|Proposta|Trattativa|Vinta|Persa","importo":null}
Regole: calcola le date relative partendo da oggi. Non inventare dati che l'utente non ha detto. Se un nome non corrisponde a nessuna persona e non è chiaro che vada creato, non creare azioni e chiedi chiarimenti nella risposta. Se l'utente non può scrivere, non proporre azioni. Le risposte alle domande devono essere brevi, in italiano, con un elenco puntato se servono più nomi.`;

return [{
  json: {
    _dest: 'claude',
    chat_id,
    testo_utente: ingresso.testo_utente,
    persone: Object.fromEntries((ctx.persone || []).map((p) => [p.id, p.nome])),
    trattative: Object.fromEntries((ctx.trattative || []).map((t) => [t.id, t.titolo])),
    puo_scrivere: !!ctx.puo_scrivere,
    richiesta_claude: {
      model: CFG.modello,
      max_tokens: 8000,
      output_config: { effort: CFG.effort },
      fallbacks: 'default',
      messages: [{ role: 'user', content: istruzioni }],
    },
  },
}];

// Legge la risposta di Claude e prepara il riepilogo da confermare.
const req = $('Prepara richiesta Claude').first().json;
const r = $json;
const chat_id = req.chat_id;

const TIPI = ['crea_persona', 'aggiorna_persona', 'crea_relazione', 'registra_contatto', 'crea_attivita', 'aggiungi_nota', 'crea_trattativa', 'aggiorna_trattativa'];
const REL = { conoscenza: 'si conoscono', amicizia: 'amicizia', parentela: 'parentela', collaborazione: 'lavorano insieme', presentazione: 'ha presentato', socio: 'soci', cliente: 'cliente di', fornitore: 'fornitore di' };

if (r.error || r.stop_reason === 'refusal') {
  return [{ json: { _dest: 'rispondi', chat_id, testo: 'Non sono riuscito a interpretare il messaggio. Riprova tra poco o riformulalo.' } }];
}
const testo = (r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
let out;
try {
  const inizio = testo.indexOf('{'), fine = testo.lastIndexOf('}');
  out = JSON.parse(testo.slice(inizio, fine + 1));
} catch (e) {
  return [{ json: { _dest: 'rispondi', chat_id, testo: 'Non ho capito. Puoi ripetere con altre parole?' } }];
}

const azioni = (Array.isArray(out.azioni) ? out.azioni : []).filter((a) => a && TIPI.includes(a.tipo));
const nuovi = new Set(azioni.filter((a) => a.tipo === 'crea_persona').map((a) => String(a.nome).toLowerCase()));
const nome = (ref) => req.persone[ref] || (ref && nuovi.has(String(ref).toLowerCase()) ? `${ref} (nuovo)` : ref || '—');
const data = (d) => (d ? new Date(`${d}T12:00:00`).toLocaleDateString('it-IT', { weekday: 'short', day: 'numeric', month: 'short' }) : '');
const eur = (n) => (Number(n) || 0).toLocaleString('it-IT', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 });

const riga = (a) => {
  switch (a.tipo) {
    case 'crea_persona': return `➕ Nuovo contatto: ${a.nome}${a.ruolo ? `, ${a.ruolo}` : ''}${a.citta ? `, ${a.citta}` : ''}${a.telefono ? `, ${a.telefono}` : ''}`;
    case 'aggiorna_persona': return `✏️ ${nome(a.persona)}: ${Object.entries(a.campi || {}).map(([k, v]) => `${k} → ${v}`).join(', ')}`;
    case 'crea_relazione': return `🔗 ${nome(a.da)} — ${REL[a.relazione] || a.relazione} — ${nome(a.a)}`;
    case 'registra_contatto': return `📞 Contatto con ${nome(a.persona)}: ${a.testo}`;
    case 'crea_attivita': return `⏰ ${a.testo}${a.persona ? ` (${nome(a.persona)})` : ''} · ${data(a.data)}${a.ora ? ` alle ${a.ora}` : ''}`;
    case 'aggiungi_nota': return `📝 Nota su ${nome(a.persona)}: ${a.testo}`;
    case 'crea_trattativa': return `💼 Nuova trattativa: ${a.titolo}${a.persona ? ` (${nome(a.persona)})` : ''} · ${eur(a.importo)}`;
    case 'aggiorna_trattativa': return `💼 ${req.trattative[a.trattativa] || a.trattativa}${a.fase ? ` → ${a.fase}` : ''}${a.importo ? ` · ${eur(a.importo)}` : ''}`;
  }
  return '';
};

const risposta = String(out.risposta || '').trim();
if (!azioni.length || !req.puo_scrivere) {
  const extra = azioni.length && !req.puo_scrivere ? '\n\nCon il tuo ruolo puoi solo consultare il CRM.' : '';
  return [{ json: { _dest: 'rispondi', chat_id, testo: (risposta || 'Non ho trovato modifiche da fare.') + extra } }];
}
const elenco = azioni.map(riga).join('\n');
return [{
  json: {
    _dest: 'proponi',
    chat_id,
    testo_utente: req.testo_utente,
    azioni,
    risposta,
    testo: `${risposta ? `${risposta}\n\n` : ''}Ho capito queste modifiche:\n${elenco}\n\nLe salvo?`,
  },
}];

// Trasforma l'esito del database in un messaggio per Telegram.
const p = $('Tipo di messaggio').first().json;
const r = $json;
if (r.stato === 'scartato') return [{ json: { chat_id: p.chat_id, testo: 'Va bene, non ho salvato niente.' } }];
if (r.stato !== 'confermato' || !Array.isArray(r.esito)) {
  return [{ json: { chat_id: p.chat_id, testo: (r.message || r.error) ? 'Questo comando non è più valido.' : 'Comando già gestito.' } }];
}
const ok = r.esito.filter((e) => e.ok).length;
const ko = r.esito.filter((e) => !e.ok);
let testo = `✅ Salvate ${ok} modifiche.`;
if (ko.length) testo += `\n⚠️ ${ko.length} non salvate: ${ko.map((e) => e.errore).join('; ')}.`;
return [{ json: { chat_id: p.chat_id, testo } }];

// Risposta al comando /collega email codice.
const t = $('Tipo di messaggio').first().json;
if (t.errore) return [{ json: { chat_id: t.chat_id, testo: t.errore } }];
const r = $json;
if (r.ok) return [{ json: { chat_id: t.chat_id, testo: `✅ ${r.messaggio}. Da ora può mandarmi vocali e messaggi.` } }];
return [{ json: { chat_id: t.chat_id, testo: `⚠️ ${r.errore || 'Non sono riuscito a collegare questo utente.'}` } }];
